SELECT id, paid_at, SUM(amount) OVER (PARTITION BY status ORDER BY paid_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_amount, SUM(amount) OVER (PARTITION BY status, order_id ORDER BY amount ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_amount_2, ROUND(amount / SUM(amount) OVER (PARTITION BY status), 4) amount_share, NTILE(3) OVER (PARTITION BY order_id, status ORDER BY amount DESC, id ASC) amount_bucket FROM payments;
